@functools.lru_cache(maxsize=None)
def _resident_programs(device_index):
    """Number of resident vector-core programs on the device (runtime query).

    The contiguous/broadcast cross kernels are launch-dispatch bound when the
    grid holds thousands of tiny blocks: the Ascend runtime serializes each
    block as a separate dispatch wave, and per-block work is too small to
    amortize it (measured ~2.37ms vs ~0.20ms for the same math). Launching one
    persistent program per resident vector core and striding blocks with
    tl.num_programs(0) collapses this to the compiler's internal block loop.
    The count is queried at runtime (vector_core_num, falling back to the
    CUDA-compatible multi_processor_count) rather than hard-coded, so it stays
    correct across Ascend variants (910B2/B4 etc.).
    """
    try:
        props = torch.npu.get_device_properties(device_index)
    except Exception:
        return None
    for attr in ("vector_core_num", "multi_processor_count"):
        try:
            value = getattr(props, attr, None)
        except Exception:
            value = None
        if value is not None:
            try:
                value = int(value)
            except Exception:
                continue
            if value > 0:
                return value
    return None


@functools.lru_cache(maxsize=None)
def _l2_bytes(device_index):
    """L2 cache size in bytes (runtime query), used to decide when the two
    inputs of a dim-last cross are small enough to be L2-resident."""
    try:
        props = torch.npu.get_device_properties(device_index)
    except Exception:
        return None
    try:
        value = int(props.l2_cache_size)
    except Exception:
        return None
    return value if value > 0 else None


@triton.jit
def _real_cross_component(lhs_a, rhs_a, lhs_b, rhs_b, ELEMENT_TY: tl.constexpr):
    if tl.constexpr(ELEMENT_TY == tl.float16) or tl.constexpr(
        ELEMENT_TY == tl.bfloat16
    ):
        return (
            lhs_a.to(tl.float32) * rhs_a.to(tl.float32)
            - lhs_b.to(tl.float32) * rhs_b.to(tl.float32)
        ).to(ELEMENT_TY, fp_downcast_rounding="rtne")
    return lhs_a * rhs_a - lhs_b * rhs_b


@triton.jit
def _cross_contig_kernel(
    input_ptr, other_ptr, output_ptr, num_vectors, BLOCK_SIZE: tl.constexpr
):
    # Contiguous dim-last fast path. Load x and y as one flat coalesced vector
    # each (BLOCK_SIZE*4 lanes, masked to BLOCK_SIZE*3 valid elements), then
    # extract the next/last cross component in registers via component % 3 and
    # tl.gather. This avoids the stride-3 gathers that starve the vector pipe.
    # Persistent launch: grid == resident vector-core count; each program walks
    # blocks b in {pid, pid+NPROG, ...} so a small grid drives the compiler's
    # internal block loop instead of one runtime dispatch per tiny block.
    num_blocks = (num_vectors + BLOCK_SIZE - 1) // BLOCK_SIZE
    pid = tl.program_id(0)
    nprog = tl.num_programs(0)
    for b in range(pid, num_blocks, nprog):
        local_offsets = tl.arange(0, BLOCK_SIZE * 4)
        valid_local = local_offsets < BLOCK_SIZE * 3
        block_start = b * BLOCK_SIZE * 3
        global_offsets = block_start + local_offsets
        num_elements = num_vectors * 3
        mask = valid_local & (global_offsets < num_elements)

        input_values = tl.load(input_ptr + global_offsets, mask=mask, other=0.0)
        other_values = tl.load(other_ptr + global_offsets, mask=mask, other=0.0)

        safe_offsets = tl.where(valid_local, local_offsets, 0)
        component = safe_offsets % 3
        vector_base = safe_offsets - component
        next_component = tl.where(component == 2, 0, component + 1)
        last_component = tl.where(component == 0, 2, component - 1)
        next_offsets = vector_base + next_component
        last_offsets = vector_base + last_component
        input_next = tl.gather(input_values, next_offsets, axis=0)
        input_last = tl.gather(input_values, last_offsets, axis=0)
        other_next = tl.gather(other_values, next_offsets, axis=0)
        other_last = tl.gather(other_values, last_offsets, axis=0)

        output_values = _real_cross_component(
            input_next,
            other_last,
            input_last,
            other_next,
            input_ptr.dtype.element_ty,
        )
        tl.store(output_ptr + global_offsets, output_values, mask=mask)


