@triton.jit
def _cross_dim1_small_inner_kernel(
    input_ptr,
    other_ptr,
    output_ptr,
    num_batches,
    INNER_SIZE: tl.constexpr,
    INPUT_BATCH_STRIDE: tl.constexpr,
    OTHER_BATCH_STRIDE: tl.constexpr,
    BATCH_BLOCK_SIZE: tl.constexpr,
    INNER_BLOCK_SIZE: tl.constexpr,
):
    # 3D dim=1 with tiny inner dimension (<=16). Tile batches x inner in one
    # program so the small inner axis does not serialize the launch. Persistent
    # launch: one program per resident vector core strides batch blocks, so the
    # flat grid of thousands of tiny tiles collapses into the compiler's
    # internal block loop (the same launch-dispatch fix as the dim-last paths).
    num_blocks = (num_batches + BATCH_BLOCK_SIZE - 1) // BATCH_BLOCK_SIZE
    pid = tl.program_id(0)
    nprog = tl.num_programs(0)
    inner = tl.arange(0, INNER_BLOCK_SIZE)
    inner_mask = inner[None, :] < INNER_SIZE
    for blk in range(pid, num_blocks, nprog):
        batches = blk * BATCH_BLOCK_SIZE + tl.arange(0, BATCH_BLOCK_SIZE)
        batch_mask = batches[:, None] < num_batches

        if INPUT_BATCH_STRIDE == 0:
            input_base = inner[None, :]
            input_mask = inner_mask
        else:
            input_base = batches[:, None] * INPUT_BATCH_STRIDE + inner[None, :]
            input_mask = batch_mask & inner_mask
        if OTHER_BATCH_STRIDE == 0:
            other_base = inner[None, :]
            other_mask = inner_mask
        else:
            other_base = batches[:, None] * OTHER_BATCH_STRIDE + inner[None, :]
            other_mask = batch_mask & inner_mask

        input_0 = tl.load(input_ptr + input_base, mask=input_mask, other=0.0)
        input_1 = tl.load(
            input_ptr + input_base + INNER_SIZE, mask=input_mask, other=0.0
        )
        input_2 = tl.load(
            input_ptr + input_base + 2 * INNER_SIZE, mask=input_mask, other=0.0
        )
        other_0 = tl.load(other_ptr + other_base, mask=other_mask, other=0.0)
        other_1 = tl.load(
            other_ptr + other_base + INNER_SIZE, mask=other_mask, other=0.0
        )
        other_2 = tl.load(
            other_ptr + other_base + 2 * INNER_SIZE, mask=other_mask, other=0.0
        )

        output_base = batches[:, None] * (3 * INNER_SIZE) + inner[None, :]
        output_mask = batch_mask & inner_mask
        element_ty = input_ptr.dtype.element_ty
        output_0 = _real_cross_component(input_1, other_2, input_2, other_1, element_ty)
        output_1 = _real_cross_component(input_2, other_0, input_0, other_2, element_ty)
        output_2 = _real_cross_component(input_0, other_1, input_1, other_0, element_ty)
        tl.store(output_ptr + output_base, output_0, mask=output_mask)
        tl.store(output_ptr + output_base + INNER_SIZE, output_1, mask=output_mask)
        tl.store(output_ptr + output_base + 2 * INNER_SIZE, output_2, mask=output_mask)


@triton.jit
def _cross_general_kernel(
    x_ptr,
    y_ptr,
    out_ptr,
    shape_ptr,
    x_stride_ptr,
    y_stride_ptr,
    out_stride_ptr,
    sd_x,
    sd_y,
    sd_out,
    batch,
    NDIM: tl.constexpr,
    BLOCK: tl.constexpr,
):
    # General strided/broadcast fallback (ndim > 3, non-contiguous, or
    # broadcast along the inner axis). `shape_ptr` is the broadcast output shape
    # with the cross axis set to 1. Each batch index b is decomposed over that
    # shape (row-major) and mapped to x/y/out bases via per-axis aligned strides
    # (broadcast axes carry stride 0). Cross lanes sit at base + k*sd_*.
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < batch
    rem = offs
    obase = tl.zeros([BLOCK], dtype=tl.int32)
    xbase = tl.zeros([BLOCK], dtype=tl.int32)
    ybase = tl.zeros([BLOCK], dtype=tl.int32)
    for i in tl.static_range(NDIM - 1, -1, -1):
        s = tl.load(shape_ptr + i)
        coord = rem % s
        rem = rem // s
        obase += coord * tl.load(out_stride_ptr + i)
        xbase += coord * tl.load(x_stride_ptr + i)
        ybase += coord * tl.load(y_stride_ptr + i)

    x0 = tl.load(x_ptr + xbase, mask=mask).to(tl.float32)
    x1 = tl.load(x_ptr + xbase + sd_x, mask=mask).to(tl.float32)
    x2 = tl.load(x_ptr + xbase + 2 * sd_x, mask=mask).to(tl.float32)
    y0 = tl.load(y_ptr + ybase, mask=mask).to(tl.float32)
    y1 = tl.load(y_ptr + ybase + sd_y, mask=mask).to(tl.float32)
    y2 = tl.load(y_ptr + ybase + 2 * sd_y, mask=mask).to(tl.float32)

    o0 = x1 * y2 - x2 * y1
    o1 = x2 * y0 - x0 * y2
    o2 = x0 * y1 - x1 * y0

    tl.store(out_ptr + obase, o0.to(out_ptr.dtype.element_ty), mask=mask)
    tl.store(out_ptr + obase + sd_out, o1.to(out_ptr.dtype.element_ty), mask=mask)
    tl.store(out_ptr + obase + 2 * sd_out, o2.to(out_ptr.dtype.element_ty), mask=mask)


_NDIM_MAX = 8


def _aligned_strides(shape, strides, out_ndim, out_shape):
    """Per-output-axis strides, 0 where the input broadcasts (absent or size-1)."""
    offset = out_ndim - len(shape)
    out = [0] * out_ndim
    for i in range(out_ndim):
        ix = i - offset
        if ix < 0 or (shape[ix] == 1 and out_shape[i] > 1):
            out[i] = 0
        else:
            out[i] = int(strides[ix])
    return out


def _contiguous_strides(shape):
    n = len(shape)
    out = [1] * n
    for i in range(n - 2, -1, -1):
        out[i] = out[i + 1] * shape[i + 1]
    return out


def cross(input, other, dim=None):
    ndim = input.dim()

    # torch.cross requires input and other to have the same number of dims.
    if input.dim() != other.dim():
        raise RuntimeError("input and other must have the same number of dimensions")

    # Normalize dim. dim=None -> first axis of input with size 3 (torch.cross).
    if dim is None:
        d_in = -1
        for i in range(ndim):
            if input.size(i) == 3:
                d_in = i
                break
        if d_in < 0:
            raise RuntimeError("no dimension of size 3 in input")
    else:
        d_in = dim if dim >= 0 else dim + ndim

    out_shape = torch.broadcast_shapes(input.shape, other.shape)
    out = torch.empty(
        out_shape,
        dtype=torch.promote_types(input.dtype, other.dtype),
        device=input.device,
    )

    batch = out.numel() // 3
    BLOCK = 256
    same_dtype = input.dtype == other.dtype

    # Fast contiguous dim-last (identical shapes, no broadcast).
    fast = (
        same_dtype
        and input.is_contiguous()
        and other.is_contiguous()
        and input.shape == out_shape
        and other.shape == out_shape
        and d_in == ndim - 1
    )
    if fast:
        resident = _resident_programs(input.device.index)
        l2 = _l2_bytes(input.device.index)
        item = input.element_size()
        small = l2 is not None and (2 * batch * 3 * item) <= l2 and batch <= 131072
        if small:
            # Small enough that both inputs sit in L2: the scalar-light
            # six-explicit-load kernel avoids the div/mod + gather scalar work.
            grid = (
                resident
                if resident is not None and batch > resident
                else triton.cdiv(batch, BLOCK)
            )
            _cross_contig_small_kernel[grid](input, other, out, batch, BLOCK_SIZE=BLOCK)
            return out
        if resident is not None and batch > resident:
            grid = (resident,)
        else:
            grid = (triton.cdiv(batch, BLOCK),)
        _cross_contig_kernel[grid](input, other, out, batch, BLOCK_SIZE=BLOCK)
        return out

    # 2D dim=-1 broadcast: [1,3] x [N,3] -> [N,3].
    if (
        same_dtype
        and ndim == 2
        and d_in == 1
        and input.is_contiguous()
        and other.is_contiguous()
    ):
        resident = _resident_programs(input.device.index)
        l2 = _l2_bytes(input.device.index)
        item = input.element_size()
        small = l2 is not None and (batch * 3 * item) <= l2
        if small:
            grid = (
                resident
                if resident is not None and batch > resident
                else triton.cdiv(batch, BLOCK)
            )
            _cross_lastdim_broadcast_small_kernel[grid](
                input,
                other,
                out,
                batch,
                INPUT_VECTORS=input.numel() // 3,
                OTHER_VECTORS=other.numel() // 3,
                BLOCK_SIZE=BLOCK,
            )
            return out
        if resident is not None and batch > resident:
            grid = (resident,)
        else:
            grid = (triton.cdiv(batch, BLOCK),)
        _cross_lastdim_broadcast_kernel[grid](
            input,
            other,
            out,
            batch,
            INPUT_VECTORS=input.numel() // 3,
            OTHER_VECTORS=other.numel() // 3,
            BLOCK_SIZE=BLOCK,
        )
        return out

    # 3D dim=1 (cross axis in the middle): [B,3,I] x [B',3,I]. Batch may
    # broadcast; the inner axis must be the same size (no inner broadcast).
    if (
        same_dtype
        and ndim == 3
        and d_in == 1
        and input.is_contiguous()
        and other.is_contiguous()
        and input.shape[2] == out_shape[2]
        and other.shape[2] == out_shape[2]
    ):
        inner = out_shape[2]
        input_batch_stride = 0 if input.shape[0] == 1 else input.stride(0)
        other_batch_stride = 0 if other.shape[0] == 1 else other.stride(0)
        if inner <= 16:
            batch_block = min(64, triton.next_power_of_2(out_shape[0]))
            inner_block = triton.next_power_of_2(inner)
            num_batch_blocks = triton.cdiv(out_shape[0], batch_block)
            resident = _resident_programs(input.device.index)
            if resident is not None and num_batch_blocks > resident:
                grid = (resident,)
            else:
                grid = (num_batch_blocks,)
            _cross_dim1_small_inner_kernel[grid](
                input,
                other,
                out,
                out_shape[0],
                INNER_SIZE=inner,
                INPUT_BATCH_STRIDE=input_batch_stride,
                OTHER_BATCH_STRIDE=other_batch_stride,
                BATCH_BLOCK_SIZE=batch_block,
                INNER_BLOCK_SIZE=inner_block,
            )
        else:
            grid = (out_shape[0], triton.cdiv(inner, BLOCK))
            _cross_dim1_3d_kernel[grid](
                input,
                other,
                out,
                INNER_SIZE=inner,
                INPUT_BATCH_STRIDE=input_batch_stride,
                OTHER_BATCH_STRIDE=other_batch_stride,
                BLOCK_SIZE=BLOCK,
            )
        return out

    # General strided fallback.
    out_ndim = len(out_shape)
    d_out = d_in + (out_ndim - ndim)
    x_strides = _aligned_strides(
        list(input.shape), list(input.stride()), out_ndim, out_shape
    )
    y_strides = _aligned_strides(
        list(other.shape), list(other.stride()), out_ndim, out_shape
    )
    out_strides = _contiguous_strides(out_shape)

    shape = list(out_shape)
    shape[d_out] = 1  # skip cross axis in the decomposition

    pad = _NDIM_MAX - out_ndim
    shape_t = torch.tensor(shape + [1] * pad, dtype=torch.int32, device=input.device)
    x_stride_t = torch.tensor(
        x_strides + [0] * pad, dtype=torch.int32, device=input.device
    )
    y_stride_t = torch.tensor(
        y_strides + [0] * pad, dtype=torch.int32, device=input.device
    )
    out_stride_t = torch.tensor(
        out_strides + [0] * pad, dtype=torch.int32, device=input.device
    )

    sd_x = int(input.stride(d_in))
    d_y = d_out - (out_ndim - other.dim())
    sd_y = int(other.stride(d_y))
    sd_out = out_strides[d_out]

    grid = (triton.cdiv(batch, BLOCK),)
    _cross_general_kernel[grid](
        input,
        other,
        out,
        shape_t,
        x_stride_t,
        y_stride_t,
        out_stride_t,
        sd_x,
        sd_y,
        sd_out,
        batch,
        NDIM=_NDIM_MAX,
        BLOCK=BLOCK,
    )

    return out
